const clean=s=>String(s??'').trim();
const num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
const nil=v=>clean(v)||null;
const emailOk=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
const companyRoles=['owner','manager','technician','operator','viewer'];
const roleLabel={owner:'Firma Sahibi',manager:'Yönetici',technician:'Teknisyen',operator:'Operatör',viewer:'Görüntüleyici'};
async function q(text,params=[]){return pool.query(text,params)}
function sign(u){return jwt.sign({id:u.id,email:u.email,name:u.name,role:u.role,platform_admin:!!u.platform_admin},JWT_SECRET,{expiresIn:'7d'})}
function setCookie(res,t){res.cookie('dm_token',t,{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',maxAge:7*24*60*60*1000})}
async function auth(req,res,next){const t=req.cookies.dm_token;if(!t)return res.status(401).json({error:'Giriş gerekli'});try{const token=jwt.verify(t,JWT_SECRET);const u=(await q('SELECT id,name,email,role,is_active,platform_admin FROM users WHERE id=$1',[token.id])).rows[0];if(!u?.is_active){res.clearCookie('dm_token');return res.status(403).json({error:'Hesabınız devre dışı'})}const st=await getSystemSettings();if(st.maintenance_mode===true&&!u.platform_admin)return res.status(503).json({error:'Sistem bakım modunda. Lütfen daha sonra tekrar deneyin.'});req.user=u;next()}catch(e){if(e?.name==='JsonWebTokenError'||e?.name==='TokenExpiredError'){res.clearCookie('dm_token');return res.status(401).json({error:'Oturum geçersiz'})}next(e)}}
async function siteAdmin(req,res,next){try{if(!req.user?.platform_admin)return res.status(403).json({error:'Platform yöneticisi yetkisi gerekli'});next()}catch(e){next(e)}}
function permit(...roles){return(req,res,next)=>{if(req.user?.platform_admin||roles.includes(req.company?.role))return next();return res.status(403).json({error:`Bu işlem için yetkiniz yok (${roleLabel[req.company?.role]||'rol'})`})}}
function healthScore(m){let s=100;if(m.status==='Arızalı')s-=35;else if(m.status==='Bakımda')s-=15;else if(m.status==='Devre dışı')s-=25;if(m.criticality==='Kritik')s-=5;s-=Math.min(24,num(m.open_faults)*6);s-=Math.min(16,num(m.critical_faults)*8);s-=Math.min(21,num(m.overdue_maintenance)*7);s-=Math.min(9,num(m.due30)*3);if(num(m.faults90)>=3)s-=8;if(m.last_maintenance_date){const days=(Date.now()-new Date(m.last_maintenance_date).getTime())/86400000;if(days>180)s-=10}else if(num(m.hours)>250)s-=8;return Math.max(5,Math.min(100,Math.round(s)))}
function slug(s){return clean(s).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ç/g,'c').replace(/ö/g,'o').replace(/ü/g,'u').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'firma'}
async function addCols(table,cols){for(const c of cols)await q(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS ${c}`)}
async function uniqueCompanyCode(name){const base=slug(name);for(let i=0;i<20;i++){const code=(base+'-'+Math.random().toString(36).slice(2,7)).slice(0,60);if(!(await q('SELECT 1 FROM companies WHERE code=$1',[code])).rows.length)return code}return base+'-'+Date.now()}
async function createPersonalCompany(user){const name=`${user.name} Atölyesi`,code=await uniqueCompanyCode(name);const c=(await q('INSERT INTO companies(name,code,owner_user_id) VALUES($1,$2,$3) RETURNING *',[name,code,user.id])).rows[0];await q("INSERT INTO company_members(company_id,user_id,role) VALUES($1,$2,'owner') ON CONFLICT(company_id,user_id) DO UPDATE SET role='owner',is_active=true",[c.id,user.id]);await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[c.id,user.id]);return c}
async function ensureCompanyForUser(userId){let u=(await q('SELECT id,name,active_company_id FROM users WHERE id=$1',[userId])).rows[0];if(!u)return null;let m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true AND c.id=$2`,[userId,u.active_company_id||0])).rows[0];if(!m)m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true ORDER BY cm.id LIMIT 1`,[userId])).rows[0];if(!m){const c=await createPersonalCompany(u);m={...c,role:'owner'}}if(Number(u.active_company_id)!==Number(m.id))await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[m.id,userId]);return m}
async function companyCtx(req,res,next){try{const c=await ensureCompanyForUser(req.user.id);if(!c)return res.status(403).json({error:'Aktif firma bulunamadı'});req.company=c;next()}catch(e){next(e)}}
async function ownMachine(id,companyId){return (await q('SELECT id FROM machines WHERE id=$1 AND company_id=$2',[id,companyId])).rows[0]}
async function audit(req,action,entityType,entityId,details={}){try{await q('INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5,$6::jsonb)',[req.company?.id||null,req.user?.id||null,action,entityType,entityId||null,JSON.stringify(details||{})])}catch(e){console.warn('audit:',e.message)}}
function validDateMonth(v){return /^\d{4}-\d{2}$/.test(String(v||''))?String(v):new Date().toISOString().slice(0,7)}
let settingsCache={at:0,data:{}};
async function getSystemSettings(force=false){if(!force&&Date.now()-settingsCache.at<10000)return settingsCache.data;const rows=(await q('SELECT key,value FROM system_settings')).rows;const data={};for(const r of rows)data[r.key]=r.value;settingsCache={at:Date.now(),data};return data}
async function adminAudit(req,action,targetType,targetId=null,details={}){try{await q('INSERT INTO admin_action_log(admin_user_id,action,target_type,target_id,details,ip,user_agent) VALUES($1,$2,$3,$4,$5::jsonb,$6,$7)',[req.user?.id||null,action,targetType,targetId||null,JSON.stringify(details||{}),String(req.ip||'').slice(0,80),String(req.get?.('user-agent')||'').slice(0,500)])}catch(e){console.warn('admin audit:',e.message)}}
async function loginEvent(req,email,success,userId=null,reason=''){try{await q('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent) VALUES($1,$2,$3,$4,$5,$6)',[userId||null,clean(email).toLowerCase(),!!success,clean(reason).slice(0,160),String(req.ip||'').slice(0,80),String(req.get('user-agent')||'').slice(0,500)])}catch(e){console.warn('login event:',e.message)}}

function resetTokenHash(token){return crypto.createHash('sha256').update(String(token||'')).digest('hex')}
async function sendPasswordResetMail(to,name,resetUrl){
 const key=clean(process.env.RESEND_API_KEY),from=clean(process.env.PASSWORD_RESET_FROM);
 if(!key||!from)return false;
 const body={from,to:[to],subject:'Dijital Makinacı • Şifre yenileme',html:`<div style="font-family:Arial,sans-serif;background:#071015;color:#eef5f3;padding:28px"><div style="max-width:560px;margin:auto;background:#0b171d;border:1px solid #20343d;border-radius:16px;padding:28px"><h2 style="margin:0 0 14px;color:#65ef9b">Şifreni yenile</h2><p>Merhaba ${clean(name)||'kullanıcı'}, Dijital Makinacı hesabın için şifre yenileme isteği aldık.</p><p><a href="${resetUrl}" style="display:inline-block;background:#65ef9b;color:#06110a;text-decoration:none;font-weight:700;padding:12px 18px;border-radius:9px">Yeni şifre oluştur</a></p><p style="color:#91a4ab;font-size:13px">Bu bağlantı 30 dakika geçerlidir ve yalnızca bir kez kullanılabilir. Bu isteği sen yapmadıysan e-postayı yok sayabilirsin.</p></div></div>`};
 const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${key}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
 if(!r.ok){const t=await r.text().catch(()=>'');throw Error(`E-posta servisi ${r.status}: ${t.slice(0,180)}`)}
 return true;
}

async function initDb(){
 await q(`CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(200) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'user',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS companies(id BIGSERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,code VARCHAR(80) UNIQUE NOT NULL,owner_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS company_members(id BIGSERIAL PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(30) NOT NULL DEFAULT 'viewer',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(company_id,user_id))`);
 await addCols('users',['active_company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS machines(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,model VARCHAR(160) DEFAULT '',hours NUMERIC(12,1) DEFAULT 0,criticality VARCHAR(30) DEFAULT 'Normal',serial_no VARCHAR(120) DEFAULT '',note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('machines',["company_id BIGINT","manufacturer VARCHAR(160) DEFAULT ''","category VARCHAR(100) DEFAULT ''","location VARCHAR(180) DEFAULT ''","status VARCHAR(30) DEFAULT 'Çalışıyor'","power_kw NUMERIC(10,2) DEFAULT 0","year INTEGER","last_maintenance_date DATE","next_maintenance_date DATE","lubricant VARCHAR(180) DEFAULT ''","bearing_info TEXT DEFAULT ''","belt_info TEXT DEFAULT ''","motor_info TEXT DEFAULT ''"]);
 await q(`CREATE TABLE IF NOT EXISTS maintenance(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE CASCADE,task VARCHAR(220) NOT NULL,due_date DATE NOT NULL,priority VARCHAR(30) DEFAULT 'Normal',status VARCHAR(20) DEFAULT 'open',note TEXT DEFAULT '',completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('maintenance',["company_id BIGINT","maintenance_type VARCHAR(50) DEFAULT 'Periyodik'","frequency VARCHAR(80) DEFAULT ''","technician VARCHAR(160) DEFAULT ''","technician_user_id BIGINT","parts_used TEXT DEFAULT ''","cost NUMERIC(12,2) DEFAULT 0","duration_min INTEGER DEFAULT 0","meter_hours NUMERIC(12,1) DEFAULT 0"]);
 await q(`CREATE TABLE IF NOT EXISTS faults(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE SET NULL,system VARCHAR(40),symptom VARCHAR(180) NOT NULL,measurements JSONB DEFAULT '{}'::jsonb,note TEXT DEFAULT '',diagnosis TEXT DEFAULT '',status VARCHAR(20) DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('faults',["company_id BIGINT","severity VARCHAR(30) DEFAULT 'Orta'","root_cause TEXT DEFAULT ''","action_taken TEXT DEFAULT ''","downtime_min INTEGER DEFAULT 0","closed_at TIMESTAMPTZ"]);
 await q(`CREATE TABLE IF NOT EXISTS parts(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,part_code VARCHAR(120) DEFAULT '',category VARCHAR(80) DEFAULT '',quantity NUMERIC(12,2) DEFAULT 0,min_quantity NUMERIC(12,2) DEFAULT 0,unit VARCHAR(30) DEFAULT 'adet',location VARCHAR(140) DEFAULT '',supplier VARCHAR(180) DEFAULT '',unit_cost NUMERIC(12,2) DEFAULT 0,note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('parts',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS favorites(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_key VARCHAR(180) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,article_key))`);
 await q(`CREATE TABLE IF NOT EXISTS calc_history(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,tool VARCHAR(120) NOT NULL,input_data JSONB DEFAULT '{}'::jsonb,result TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS work_orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE SET NULL,title VARCHAR(220) NOT NULL,description TEXT DEFAULT '',priority VARCHAR(30) DEFAULT 'Normal',status VARCHAR(30) DEFAULT 'open',assigned_to VARCHAR(160) DEFAULT '',due_date DATE,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,parts_used TEXT DEFAULT '',cost NUMERIC(12,2) DEFAULT 0,downtime_min INTEGER DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('work_orders',['company_id BIGINT','assigned_user_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS machine_measurements(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,temperature NUMERIC(10,2),pressure NUMERIC(10,2),current_amp NUMERIC(10,2),voltage NUMERIC(10,2),vibration NUMERIC(10,3),rpm NUMERIC(12,1),note TEXT DEFAULT '',measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('machine_measurements',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS attachments(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,file_name VARCHAR(240) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes INTEGER NOT NULL,file_data BYTEA NOT NULL,caption VARCHAR(240) DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('attachments',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,company_id BIGINT REFERENCES companies(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT,details JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('users',["platform_admin BOOLEAN NOT NULL DEFAULT FALSE","last_login_at TIMESTAMPTZ"]);
 await q("UPDATE users SET platform_admin=true WHERE role='admin' AND platform_admin=false");
 await q(`CREATE TABLE IF NOT EXISTS system_settings(key VARCHAR(80) PRIMARY KEY,value JSONB NOT NULL DEFAULT 'null'::jsonb,updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS announcements(id BIGSERIAL PRIMARY KEY,title VARCHAR(220) NOT NULL,body TEXT NOT NULL,level VARCHAR(30) NOT NULL DEFAULT 'info',is_active BOOLEAN NOT NULL DEFAULT TRUE,publish_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS knowledge_articles(id BIGSERIAL PRIMARY KEY,slug VARCHAR(180) UNIQUE NOT NULL,title VARCHAR(240) NOT NULL,category VARCHAR(100) NOT NULL DEFAULT 'Genel',summary TEXT DEFAULT '',body TEXT NOT NULL DEFAULT '',is_published BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS admin_action_log(id BIGSERIAL PRIMARY KEY,admin_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(100) NOT NULL,target_type VARCHAR(100) NOT NULL,target_id BIGINT,details JSONB NOT NULL DEFAULT '{}'::jsonb,ip VARCHAR(80) DEFAULT '',user_agent TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS login_events(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,email VARCHAR(200) DEFAULT '',success BOOLEAN NOT NULL DEFAULT FALSE,reason VARCHAR(160) DEFAULT '',ip VARCHAR(80) DEFAULT '',user_agent TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS support_tickets(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,company_id BIGINT REFERENCES companies(id) ON DELETE SET NULL,subject VARCHAR(220) NOT NULL,message TEXT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'open',priority VARCHAR(30) NOT NULL DEFAULT 'Normal',admin_note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS password_reset_tokens(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash VARCHAR(64) UNIQUE NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,requested_ip VARCHAR(80) DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE INDEX IF NOT EXISTS idx_password_reset_token ON password_reset_tokens(token_hash,expires_at)`);
 await q(`CREATE TABLE IF NOT EXISTS part_movements(id BIGSERIAL PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,part_id BIGINT NOT NULL REFERENCES parts(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,movement_type VARCHAR(12) NOT NULL,quantity NUMERIC(12,2) NOT NULL,previous_qty NUMERIC(12,2) NOT NULL,new_qty NUMERIC(12,2) NOT NULL,note VARCHAR(240) DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE INDEX IF NOT EXISTS idx_part_movements_part ON part_movements(company_id,part_id,created_at DESC)`);
 const defaultSettings={site_name:'Dijital Makinacı',registrations_enabled:true,maintenance_mode:false,support_email:'',allow_file_uploads:true};
 for(const [k,v] of Object.entries(defaultSettings))await q('INSERT INTO system_settings(key,value) VALUES($1,$2::jsonb) ON CONFLICT(key) DO NOTHING',[k,JSON.stringify(v)]);
 settingsCache.at=0;

 const users=(await q('SELECT id,name,active_company_id FROM users ORDER BY id')).rows;
 for(const u of users)await ensureCompanyForUser(u.id);
 const shared=['machines','maintenance','faults','parts','work_orders','machine_measurements','attachments'];
 for(const t of shared)await q(`UPDATE ${t} x SET company_id=u.active_company_id FROM users u WHERE x.user_id=u.id AND x.company_id IS NULL`);
 await q('CREATE INDEX IF NOT EXISTS idx_machines_company ON machines(company_id)');
 await q('CREATE INDEX IF NOT EXISTS idx_maintenance_company_due ON maintenance(company_id,due_date)');
 await q('CREATE INDEX IF NOT EXISTS idx_faults_company_created ON faults(company_id,created_at)');
 await q('CREATE INDEX IF NOT EXISTS idx_work_company_due ON work_orders(company_id,due_date)');
 await q('CREATE INDEX IF NOT EXISTS idx_parts_company ON parts(company_id)');

 const ae=clean(process.env.ADMIN_EMAIL).toLowerCase(),ap=clean(process.env.ADMIN_PASSWORD);
 if(ae&&ap){const f=await q('SELECT id,name FROM users WHERE email=$1',[ae]);if(!f.rows.length){const h=await bcrypt.hash(ap,12);const u=(await q("INSERT INTO users(name,email,password_hash,role,platform_admin) VALUES($1,$2,$3,'admin',true) RETURNING id,name,email,role,platform_admin",[process.env.ADMIN_NAME||'Site Yöneticisi',ae,h])).rows[0];await createPersonalCompany(u)}else{await q("UPDATE users SET role='admin',platform_admin=true WHERE email=$1",[ae]);await ensureCompanyForUser(f.rows[0].id)}}
}

