app.get('/api/faults',auth,companyCtx,async(req,res)=>res.json((await q(`SELECT f.*,x.name machine_name,u.name created_by_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id LEFT JOIN users u ON u.id=f.user_id WHERE f.company_id=$1 ORDER BY CASE WHEN f.status='open' THEN 0 ELSE 1 END,f.id DESC LIMIT 400`,[req.company.id])).rows));
