app.get('/api/admin/overview',auth,siteAdmin,async(req,res,next)=>{try{const [summary,userTrend,loginTrend,critical,recent]=await Promise.all([
 q(`SELECT (SELECT COUNT(*) FROM users)::int users,(SELECT COUNT(*) FROM users WHERE is_active)::int active_users,(SELECT COUNT(*) FROM users WHERE NOT is_active)::int inactive_users,(SELECT COUNT(*) FROM users WHERE platform_admin)::int platform_admins,(SELECT COUNT(*) FROM users WHERE created_at>=NOW()-INTERVAL '7 days')::int new_users_7d,(SELECT COUNT(*) FROM companies)::int companies,(SELECT COUNT(*) FROM companies WHERE created_at>=NOW()-INTERVAL '7 days')::int new_companies_7d,(SELECT COUNT(*) FROM machines)::int machines,(SELECT COUNT(*) FROM faults WHERE status='open')::int open_faults,(SELECT COUNT(*) FROM faults WHERE status='open' AND severity='Kritik')::int critical_faults,(SELECT COUNT(*) FROM maintenance WHERE status='open' AND due_date<CURRENT_DATE)::int overdue_maintenance,(SELECT COUNT(*) FROM work_orders WHERE status<>'done')::int open_work_orders,(SELECT COUNT(*) FROM parts WHERE quantity<=min_quantity)::int low_stock,(SELECT COALESCE(SUM(size_bytes),0) FROM attachments)::bigint storage_bytes,(SELECT COUNT(*) FROM login_events WHERE success=false AND created_at>=NOW()-INTERVAL '24 hours')::int failed_logins_24h,(SELECT COUNT(*) FROM admin_action_log WHERE created_at>=NOW()-INTERVAL '24 hours')::int admin_actions_24h`),
 q(`SELECT to_char(d,'YYYY-MM-DD') day,COUNT(u.id)::int value FROM generate_series(CURRENT_DATE-29,CURRENT_DATE,'1 day') d LEFT JOIN users u ON u.created_at>=d AND u.created_at<d+INTERVAL '1 day' GROUP BY d ORDER BY d`),
 q(`SELECT to_char(d,'YYYY-MM-DD') day,(COUNT(l.id) FILTER(WHERE l.success))::int success,(COUNT(l.id) FILTER(WHERE NOT l.success))::int failed FROM generate_series(CURRENT_DATE-13,CURRENT_DATE,'1 day') d LEFT JOIN login_events l ON l.created_at>=d AND l.created_at<d+INTERVAL '1 day' GROUP BY d ORDER BY d`),
 q(`SELECT f.id,f.symptom,f.severity,f.created_at,m.name machine_name,c.name company_name FROM faults f LEFT JOIN machines m ON m.id=f.machine_id LEFT JOIN companies c ON c.id=f.company_id WHERE f.status='open' AND f.severity IN ('Kritik','Yüksek') ORDER BY CASE f.severity WHEN 'Kritik' THEN 0 ELSE 1 END,f.created_at DESC LIMIT 12`),
 q(`SELECT l.*,u.name admin_name,u.email admin_email FROM admin_action_log l LEFT JOIN users u ON u.id=l.admin_user_id ORDER BY l.id DESC LIMIT 12`)
]);res.json({summary:summary.rows[0],userTrend:userTrend.rows,loginTrend:loginTrend.rows,critical:critical.rows,recentAdmin:recent.rows})}catch(e){next(e)}});
app.get('/api/admin/summary',auth,siteAdmin,async(req,res,next)=>{try{const r=await q(`SELECT (SELECT COUNT(*) FROM users)::int users,(SELECT COUNT(*) FROM users WHERE is_active)::int active_users,(SELECT COUNT(*) FROM users WHERE NOT is_active)::int inactive_users,(SELECT COUNT(*) FROM companies)::int companies,(SELECT COUNT(*) FROM machines)::int machines,(SELECT COUNT(*) FROM maintenance)::int maintenance,(SELECT COUNT(*) FROM faults)::int faults,(SELECT COUNT(*) FROM parts)::int parts,(SELECT COUNT(*) FROM work_orders)::int work_orders,(SELECT COUNT(*) FROM attachments)::int attachments`);res.json(r.rows[0])}catch(e){next(e)}});
app.get('/api/admin/users',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status),pa=clean(req.query.platform_admin);const r=await q(`SELECT u.id,u.name,u.email,u.role,u.platform_admin,u.is_active,u.last_login_at,u.created_at,(SELECT COUNT(*) FROM company_members cm WHERE cm.user_id=u.id AND cm.is_active)::int companies,(SELECT COUNT(*) FROM machines m WHERE m.user_id=u.id)::int machines,(SELECT COUNT(*) FROM faults f WHERE f.user_id=u.id)::int faults FROM users u WHERE ($1='%%' OR u.name ILIKE $1 OR u.email ILIKE $1) AND ($2='' OR ($2='active' AND u.is_active) OR ($2='inactive' AND NOT u.is_active)) AND ($3='' OR ($3='yes' AND u.platform_admin) OR ($3='no' AND NOT u.platform_admin)) ORDER BY u.id DESC LIMIT 500`,[term,status,pa]);res.json(r.rows)}catch(e){next(e)}});
app.get('/api/admin/users/:id',auth,siteAdmin,async(req,res,next)=>{try{const u=(await q('SELECT id,name,email,role,platform_admin,is_active,last_login_at,created_at FROM users WHERE id=$1',[req.params.id])).rows[0];if(!u)return res.status(404).json({error:'Kullanıcı bulunamadı'});const [m,ma,f,p,cs,logins]=await Promise.all([q('SELECT id,name,manufacturer,model,status,created_at FROM machines WHERE user_id=$1 ORDER BY id DESC LIMIT 50',[u.id]),q('SELECT ma.id,ma.task,ma.status,ma.due_date,x.name machine_name FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.user_id=$1 ORDER BY ma.id DESC LIMIT 30',[u.id]),q('SELECT f.id,f.symptom,f.status,f.severity,f.created_at,x.name machine_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id WHERE f.user_id=$1 ORDER BY f.id DESC LIMIT 30',[u.id]),q('SELECT id,name,quantity,min_quantity,unit FROM parts WHERE user_id=$1 ORDER BY name LIMIT 30',[u.id]),q(`SELECT c.id,c.name,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active ORDER BY c.name`,[u.id]),q('SELECT success,reason,ip,created_at FROM login_events WHERE user_id=$1 ORDER BY id DESC LIMIT 20',[u.id])]);res.json({user:u,machines:m.rows,maintenance:ma.rows,faults:f.rows,parts:p.rows,companies:cs.rows,logins:logins.rows})}catch(e){next(e)}});
app.patch('/api/admin/users/:id/active',auth,siteAdmin,async(req,res,next)=>{try{if(Number(req.params.id)===Number(req.user.id)&&!req.body.is_active)return res.status(400).json({error:'Kendi platform admin hesabınızı devre dışı bırakamazsınız'});const r=await q('UPDATE users SET is_active=$1 WHERE id=$2 RETURNING id,name,email,platform_admin,is_active',[!!req.body.is_active,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'Kullanıcı bulunamadı'});await adminAudit(req,req.body.is_active?'user_enabled':'user_disabled','user',req.params.id,{email:r.rows[0].email});res.json(r.rows[0])}catch(e){next(e)}});
app.patch('/api/admin/users/:id/platform-admin',auth,siteAdmin,async(req,res,next)=>{try{const on=!!req.body.platform_admin;if(Number(req.params.id)===Number(req.user.id)&&!on)return res.status(400).json({error:'Kendi platform admin yetkinizi kaldıramazsınız'});const r=await q(`UPDATE users SET platform_admin=$1,role=CASE WHEN $1 THEN 'admin' ELSE 'user' END WHERE id=$2 RETURNING id,name,email,role,platform_admin,is_active`,[on,req.params.id]);if(!r.rows[0])return res.status(404).json({error:'Kullanıcı bulunamadı'});await adminAudit(req,on?'platform_admin_granted':'platform_admin_revoked','user',req.params.id,{email:r.rows[0].email});res.json(r.rows[0])}catch(e){next(e)}});
app.patch('/api/admin/users/:id/role',auth,siteAdmin,async(req,res,next)=>{try{const on=req.body.role==='admin';if(Number(req.params.id)===Number(req.user.id)&&!on)return res.status(400).json({error:'Kendi platform admin yetkinizi kaldıramazsınız'});const r=await q(`UPDATE users SET platform_admin=$1,role=CASE WHEN $1 THEN 'admin' ELSE 'user' END WHERE id=$2 RETURNING id,name,email,role,platform_admin,is_active`,[on,req.params.id]);if(r.rows[0])await adminAudit(req,on?'platform_admin_granted':'platform_admin_revoked','user',req.params.id,{email:r.rows[0].email});res.json(r.rows[0]||{})}catch(e){next(e)}});
app.delete('/api/admin/users/:id',auth,siteAdmin,async(req,res,next)=>{try{if(Number(req.params.id)===Number(req.user.id))return res.status(400).json({error:'Kendi platform admin hesabınızı silemezsiniz'});const u=(await q(`SELECT u.email,u.platform_admin,(SELECT COUNT(*) FROM machines WHERE user_id=u.id)::int machines,(SELECT COUNT(*) FROM maintenance WHERE user_id=u.id)::int maintenance,(SELECT COUNT(*) FROM faults WHERE user_id=u.id)::int faults,(SELECT COUNT(*) FROM parts WHERE user_id=u.id)::int parts,(SELECT COUNT(*) FROM companies WHERE owner_user_id=u.id)::int owned_companies FROM users u WHERE u.id=$1`,[req.params.id])).rows[0];if(!u)return res.status(404).json({error:'Kullanıcı bulunamadı'});const deps=num(u.machines)+num(u.maintenance)+num(u.faults)+num(u.parts)+num(u.owned_companies);if(deps>0)return res.status(409).json({error:'Bu kullanıcının operasyon kayıtları veya sahip olduğu firma var. Veri kaybını önlemek için hesabı silmek yerine pasifleştir.'});await q('DELETE FROM users WHERE id=$1',[req.params.id]);await adminAudit(req,'user_deleted','user',req.params.id,{email:u.email,was_platform_admin:u.platform_admin});res.json({ok:true})}catch(e){next(e)}});

app.get('/api/admin/companies',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`;res.json((await q(`SELECT c.id,c.name,c.code,c.created_at,u.name owner_name,u.email owner_email,(SELECT COUNT(*) FROM company_members cm WHERE cm.company_id=c.id AND cm.is_active)::int members,(SELECT COUNT(*) FROM machines m WHERE m.company_id=c.id)::int machines,(SELECT COUNT(*) FROM faults f WHERE f.company_id=c.id AND f.status='open')::int open_faults,(SELECT COUNT(*) FROM maintenance ma WHERE ma.company_id=c.id AND ma.status='open')::int open_maintenance,(SELECT COUNT(*) FROM work_orders w WHERE w.company_id=c.id AND w.status<>'done')::int open_work_orders FROM companies c LEFT JOIN users u ON u.id=c.owner_user_id WHERE ($1='%%' OR c.name ILIKE $1 OR c.code ILIKE $1 OR u.email ILIKE $1) ORDER BY c.id DESC LIMIT 500`,[term])).rows)}catch(e){next(e)}});
app.get('/api/admin/companies/:id',auth,siteAdmin,async(req,res,next)=>{try{const c=(await q(`SELECT c.*,u.name owner_name,u.email owner_email FROM companies c LEFT JOIN users u ON u.id=c.owner_user_id WHERE c.id=$1`,[req.params.id])).rows[0];if(!c)return res.status(404).json({error:'Firma bulunamadı'});const [members,machinesR,faultsR,maintR,workR]=await Promise.all([q(`SELECT u.id,u.name,u.email,cm.role,cm.is_active FROM company_members cm JOIN users u ON u.id=cm.user_id WHERE cm.company_id=$1 ORDER BY cm.id`,[c.id]),q('SELECT id,name,manufacturer,model,status,criticality FROM machines WHERE company_id=$1 ORDER BY id DESC LIMIT 100',[c.id]),q(`SELECT f.id,f.symptom,f.severity,f.status,m.name machine_name,f.created_at FROM faults f LEFT JOIN machines m ON m.id=f.machine_id WHERE f.company_id=$1 ORDER BY f.id DESC LIMIT 50`,[c.id]),q(`SELECT ma.id,ma.task,ma.status,ma.due_date,m.name machine_name FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id WHERE ma.company_id=$1 ORDER BY ma.id DESC LIMIT 50`,[c.id]),q(`SELECT w.id,w.title,w.status,w.priority,w.due_date,m.name machine_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 ORDER BY w.id DESC LIMIT 50`,[c.id])]);res.json({company:c,members:members.rows,machines:machinesR.rows,faults:faultsR.rows,maintenance:maintR.rows,workOrders:workR.rows})}catch(e){next(e)}});
