app.get('/api/admin/maintenance',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status);res.json((await q(`SELECT ma.id,ma.task,ma.maintenance_type,ma.priority,ma.status,ma.due_date,ma.completed_at,ma.cost,ma.duration_min,m.name machine_name,c.name company_name,u.name created_by FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id LEFT JOIN companies c ON c.id=ma.company_id LEFT JOIN users u ON u.id=ma.user_id WHERE ($1='%%' OR ma.task ILIKE $1 OR m.name ILIKE $1 OR c.name ILIKE $1) AND ($2='' OR ma.status=$2) ORDER BY ma.id DESC LIMIT 700`,[term,status])).rows)}catch(e){next(e)}});
app.get('/api/admin/work-orders',auth,siteAdmin,async(req,res,next)=>{try{const term=`%${clean(req.query.search)}%`,status=clean(req.query.status);res.json((await q(`SELECT w.id,w.title,w.priority,w.status,w.assigned_to,w.due_date,w.cost,w.downtime_min,w.created_at,m.name machine_name,c.name company_name,u.name created_by FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id LEFT JOIN companies c ON c.id=w.company_id LEFT JOIN users u ON u.id=w.user_id WHERE ($1='%%' OR w.title ILIKE $1 OR m.name ILIKE $1 OR c.name ILIKE $1 OR w.assigned_to ILIKE $1) AND ($2='' OR w.status=$2) ORDER BY w.id DESC LIMIT 700`,[term,status])).rows)}catch(e){next(e)}});

