app.get('/api/admin/articles',auth,siteAdmin,async(req,res,next)=>{try{res.json((await q(`SELECT a.*,u.name updated_by_name FROM knowledge_articles a LEFT JOIN users u ON u.id=a.updated_by ORDER BY a.updated_at DESC LIMIT 300`)).rows)}catch(e){next(e)}});
app.post('/api/admin/articles',auth,siteAdmin,async(req,res,next)=>{try{const title=clean(req.body.title),category=clean(req.body.category)||'Genel',summary=clean(req.body.summary),body=clean(req.body.body);if(title.length<3||body.length<5)return res.status(400).json({error:'Başlık ve içerik gerekli'});const base=slug(req.body.slug||title);let articleSlug=base;for(let i=1;(await q('SELECT 1 FROM knowledge_articles WHERE slug=$1',[articleSlug])).rows.length;i++)articleSlug=`${base}-${i+1}`;const r=(await q(`INSERT INTO knowledge_articles(slug,title,category,summary,body,is_published,created_by,updated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$7) RETURNING *`,[articleSlug,title,category,summary,body,req.body.is_published!==false,req.user.id])).rows[0];await adminAudit(req,'article_created','article',r.id,{title,slug:articleSlug});res.status(201).json(r)}catch(e){next(e)}});
